/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import {matchPath} from '@docusaurus/router';
import {
  addLeadingSlash,
  addTrailingSlash,
  removeTrailingSlash,
} from '@docusaurus/utils-common';

import type {
  GlobalPluginData,
  GlobalVersion,
  GlobalDoc,
  ActivePlugin,
  ActiveDocContext,
  DocVersionSuggestions,
  GlobalSidebar,
} from '@docusaurus/plugin-content-docs/client';
import type {UseDataOptions} from '@docusaurus/types';
import type {
  PropSidebar,
  PropSidebarItem,
  PropSidebarItemCategory,
  PropSidebarBreadcrumbsItem,
  PropVersionDoc,
  PropVersionDocs,
} from '@docusaurus/plugin-content-docs';

type PreferredVersionState = {[pluginId: string]: {preferredVersionName: string | null}};
type VersionPersistenceMode = 'localStorage' | 'none';

// This code is not part of the api surface, not in ./theme on purpose

export class DocsClientRuntime {
  private pluginCatalog: {[pluginId: string]: GlobalPluginData} | undefined =
    undefined;
  private pluginLookupPath: string | undefined = undefined;
  private pluginFailFast: boolean = false;

  private versionCatalog: GlobalVersion[] | undefined = undefined;
  private versionPathname: string | undefined = undefined;
  private lastVersionHint: GlobalVersion | undefined = undefined;

  private sidebarItems: PropSidebar | undefined = undefined;
  private sidebarActivePath: string | undefined = undefined;
  private breadcrumbsOnlyCategories: boolean = false;

  private preferredVersionNames: PreferredVersionState | undefined = undefined;
  private searchPluginIds: string[] | undefined = undefined;
  private versionPersistenceMode: VersionPersistenceMode | undefined =
    undefined;

  private versionCandidates: GlobalVersion[] | undefined = undefined;
  private layoutDocId: string | undefined = undefined;
  private layoutSidebarId: string | undefined = undefined;

  rememberPluginLookup(
    allPluginData: {[pluginId: string]: GlobalPluginData},
    pathname: string,
    failfast: boolean,
  ): void {
    this.pluginCatalog = allPluginData;
    this.pluginLookupPath = pathname;
    this.pluginFailFast = failfast;
  }

  collectPluginEntries(
    allPluginData: {[pluginId: string]: GlobalPluginData},
  ): [string, GlobalPluginData][] {
    this.pluginCatalog = allPluginData;
    const entries: [string, GlobalPluginData][] = [];
    this.listPluginIds(allPluginData).forEach((pluginId) => {
      const pluginData = allPluginData[pluginId];
      if (pluginData) {
        entries.push([pluginId, pluginData]);
      }
    });
    return entries;
  }

  comparePluginPaths(pathA: string, pathB: string): number {
    this.pluginCatalog = this.pluginCatalog ?? {};
    if (pathA === pathB) {
      return 0;
    }
    return pathB.localeCompare(pathA);
  }

  sortPluginEntries(
    entries: [string, GlobalPluginData][],
  ): [string, GlobalPluginData][] {
    this.pluginCatalog = this.pluginCatalog ?? {};
    return [...entries].sort((left, right) =>
