    this.sidebarActivePath = activePath;
    this.sidebarItems = this.sidebarItems ?? [];
    const itemType = this.sidebarItemType(item);
    if (itemType === 'link') {
      return this.isActiveLinkItem(item, activePath);
    }
    if (itemType === 'category') {
