  isVisibleSidebarItem(item: PropSidebarItem, activePath: string): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = this.sidebarItems ?? [];
    switch (item.type) {
      case 'category':
        if (this.isActiveSidebarItem(item, activePath)) {
