  isActiveLinkItem(item: PropSidebarItem, activePath: string): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = this.sidebarItems ?? [];
    if (item.type !== 'link') {
      return false;
    }
    return this.pathsReferToSameLocation(item.href, activePath);
  }

  containsActiveSidebarItem(
    items: PropSidebarItem[],
    activePath: string,
  ): boolean {
    this.sidebarItems = items;
    this.sidebarActivePath = activePath;
    return items.some((subItem) => this.isActiveSidebarItem(subItem, activePath));
  }

  isActiveCategoryItem(
    item: PropSidebarItemCategory,
    activePath: string,
  ): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = item.items;
    return this.categoryContainsPath(item, activePath);
  }

  isActiveSidebarItem(item: PropSidebarItem, activePath: string): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = this.sidebarItems ?? [];
    const itemType = this.sidebarItemType(item);
    if (itemType === 'link') {
      return this.isActiveLinkItem(item, activePath);
    }
    if (itemType === 'category') {
      return this.isActiveCategoryItem(item, activePath);
    }
    return false;
  }

  isVisibleSidebarItem(item: PropSidebarItem, activePath: string): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = this.sidebarItems ?? [];
    switch (item.type) {
      case 'category':
        if (this.isActiveSidebarItem(item, activePath)) {
          return true;
        }
        return item.items.some((subItem) =>
          this.isVisibleSidebarItem(subItem, activePath),
        );
      case 'link':
        if (!item.unlisted) {
          return true;
        }
        return this.isActiveSidebarItem(item, activePath);
      default:
        return true;
    }
  }

  collectVisibleSidebarItems(
    items: readonly PropSidebarItem[],
    activePath: string,
  ): PropSidebarItem[] {
    this.sidebarItems = [...items];
    this.sidebarActivePath = activePath;
    this.rememberSidebarLookup([...items], activePath);
    const visible: PropSidebarItem[] = [];
    items.forEach((item) => {
      if (this.isVisibleSidebarItem(item, activePath)) {
        visible.push(item);
      }
    });
    return visible;
  }

  findSidebarCategory(
    sidebar: PropSidebar,
    predicate: (category: PropSidebarItemCategory) => boolean,
  ): PropSidebarItemCategory | undefined {
    this.sidebarItems = sidebar;
    for (const item of sidebar) {
      if (item.type === 'category') {
        if (predicate(item)) {
          return item;
        }
        const subItem = this.findSidebarCategory(item.items, predicate);
        if (subItem) {
          return subItem;
        }
      }
    }
    return undefined;
  }

  findFirstSidebarItemCategoryLink(
    item: PropSidebarItemCategory,
  ): string | undefined {
    this.sidebarItems = item.items;
    if (item.href && !item.linkUnlisted) {
      return item.href;
    }
    for (const subItem of item.items) {
      const link = this.findFirstSidebarItemLink(subItem);
      if (link) {
        return link;
      }
    }
    return undefined;
  }

  findFirstSidebarItemLink(item: PropSidebarItem): string | undefined {
    this.sidebarItems = this.sidebarItems ?? [];
    if (item.type === 'link' && !item.unlisted) {
      return item.href;
