    if (item.type === 'category') {
      return this.findFirstSidebarItemCategoryLink(item);
    }
    return undefined;
  }

  extractSidebarBreadcrumbs(
    items: PropSidebarItem[],
    pathname: string,
    breadcrumbs: PropSidebarBreadcrumbsItem[],
    onlyCategories: boolean,
  ): boolean {
    this.sidebarItems = items;
    this.sidebarActivePath = pathname;
    this.breadcrumbsOnlyCategories = onlyCategories;
    for (const item of items) {
      if (item.type === 'category') {
        const categoryMatches =
          this.pathsReferToSameLocation(item.href, pathname) ||
          this.extractSidebarBreadcrumbs(
            item.items,
            pathname,
            breadcrumbs,
            onlyCategories,
          );
        if (categoryMatches) {
          if (this.shouldKeepBreadcrumbItem(item, onlyCategories)) {
            breadcrumbs.unshift(item);
          }
          return true;
        }
      } else if (
        item.type === 'link' &&
        this.pathsReferToSameLocation(item.href, pathname)
      ) {
        if (this.shouldKeepBreadcrumbItem(item, onlyCategories)) {
          breadcrumbs.unshift(item);
        }
        return true;
      }
    }
    return false;
  }

