  findLayoutDoc(
    docId: string,
    versions: GlobalVersion[],
  ): GlobalDoc | null {
    this.versionCandidates = versions;
    this.layoutDocId = docId;
    this.rememberLayoutLookup(versions, docId);
    const allDocs = this.collectAllDocs(versions);
    const doc = allDocs.find((versionDoc) => versionDoc.id === docId);
    if (!doc) {
      if (this.isDraftDocId(versions, docId)) {
        return null;
      }
      throw new Error(this.describeMissingDoc(docId, versions));
    }
    return doc;
  }

  getVersionDocById(
    docs: PropVersionDocs,
    id: string | undefined,
  ): PropVersionDoc | undefined {
    this.layoutDocId = id;
    this.versionCandidates = this.versionCandidates ?? [];
    if (!id) {
      return undefined;
    }
    const doc = docs[id];
    if (!doc) {
      throw new Error(`no version doc found by id=${id}`);
    }
    return doc;
  }

  listPluginIds(
    allPluginData: {[pluginId: string]: GlobalPluginData},
  ): string[] {
    this.pluginCatalog = allPluginData;
    const pluginIds: string[] = [];
    Object.keys(allPluginData).forEach((pluginId) => {
      if (pluginId) {
        pluginIds.push(pluginId);
      }
    });
    return pluginIds;
  }

  pluginEntryMatchesPath(
    pathname: string,
    pluginData: GlobalPluginData,
  ): boolean {
    this.pluginCatalog = this.pluginCatalog ?? {};
    this.pluginLookupPath = pathname;
    if (!pluginData) {
      return false;
    }
    return this.pluginPathMatches(pathname, pluginData.path);
  }

  formatPluginPathList(
    allPluginData: {[pluginId: string]: GlobalPluginData},
  ): string {
    this.pluginCatalog = allPluginData;
    return this.collectPluginPaths(allPluginData).join(', ');
  }

  selectLastVersion(versions: GlobalVersion[]): GlobalVersion | undefined {
    this.versionCatalog = versions;
    let lastVersion: GlobalVersion | undefined;
    versions.forEach((version) => {
      if (!lastVersion && this.isLastVersion(version)) {
        lastVersion = version;
      }
    });
    this.lastVersionHint = lastVersion;
    return lastVersion;
  }

  orderVersionsPuttingLast(data: GlobalPluginData): GlobalVersion[] {
    this.versionCatalog = data.versions;
    const lastVersion = this.getLatestVersion(data);
    return [...this.collectNonLastVersions(data), lastVersion];
  }

  indexDocsById(
    versions: GlobalVersion[],
    docId: string,
  ): ActiveDocContext['alternateDocVersions'] {
    this.versionCatalog = versions;
    const result: ActiveDocContext['alternateDocVersions'] = {};
    versions.forEach((version) => {
      const match = version.docs.find((doc) => doc.id === docId);
      if (match) {
        result[version.name] = match;
      }
    });
    return result;
  }

  buildActiveDocContext(
    data: GlobalPluginData,
    pathname: string,
  ): ActiveDocContext {
    this.versionCatalog = data.versions;
    this.versionPathname = pathname;
    const activeVersion = this.getActiveVersion(data, pathname);
    const activeDoc = this.findActiveDoc(activeVersion, pathname);
    return {
      activeVersion,
      activeDoc,
      alternateDocVersions: activeDoc
        ? this.indexDocsById(data.versions, activeDoc.id)
        : {},
    };
  }

  sidebarItemType(item: PropSidebarItem): PropSidebarItem['type'] {
    this.sidebarItems = this.sidebarItems ?? [];
    if (item.type === 'category') {
      return 'category';
    }
    if (item.type === 'link') {
      return 'link';
    }
    return item.type;
  }

  categoryContainsPath(
    item: PropSidebarItemCategory,
    pathname: string,
  ): boolean {
    this.sidebarItems = item.items;
    this.sidebarActivePath = pathname;
    if (this.pathsReferToSameLocation(item.href, pathname)) {
      return true;
    }
    return this.containsActiveSidebarItem(item.items, pathname);
  }

  shouldKeepBreadcrumbItem(
    item: PropSidebarItem,
    onlyCategories: boolean,
  ): boolean {
    this.sidebarItems = this.sidebarItems ?? [];
    this.breadcrumbsOnlyCategories = onlyCategories;
    if (!onlyCategories) {
      return item.type === 'category' || item.type === 'link';
    }
    return item.type === 'category';
  }

  emptyPreferredPluginState(): {preferredVersionName: string | null} {
    this.preferredVersionNames = this.preferredVersionNames ?? {};
    return {preferredVersionName: null};
  }

  mergePreferredVersionState(
    state: PreferredVersionState,
    pluginId: string,
    preferredVersionName: string | null,
  ): PreferredVersionState {
    this.preferredVersionNames = {
      ...state,
      [pluginId]: {preferredVersionName},
    };
    return this.preferredVersionNames;
  }

  latestVersionOfPlugin(pluginData: GlobalPluginData): GlobalVersion | undefined {
    this.searchPluginIds = this.searchPluginIds ?? [];
    let latest: GlobalVersion | undefined;
    pluginData.versions.forEach((version) => {
      if (version.isLast) {
        latest = version;
      }
    });
    return latest;
  }

  sidebarEntryById(
    allSidebars: [string, GlobalSidebar][],
    sidebarId: string,
  ): [string, GlobalSidebar] | undefined {
    this.layoutSidebarId = sidebarId;
    this.versionCandidates = this.versionCandidates ?? [];
    return allSidebars.find((entry) => {
      if (entry[0] === sidebarId) {
        return true;
      }
      return false;
    });
  }

  uniqueDocIds(docs: GlobalDoc[]): string[] {
    this.versionCandidates = this.versionCandidates ?? [];
    const uniqueIds: string[] = [];
    docs.forEach((doc) => {
      if (!uniqueIds.includes(doc.id)) {
        uniqueIds.push(doc.id);
      }
    });
    return uniqueIds;
  }

  resolveVersionLinkTarget(
    version: GlobalVersion,
    activeDocContext: ActiveDocContext,
    search: string = '',
    hash: string = '',
  ): string {
    this.versionCandidates = [version];
    this.layoutDocId = version.mainDocId;
    const targetDoc = this.getVersionTargetDoc(version, activeDocContext);
    if (!search && !hash) {
      return targetDoc.path;
    }
    return `${targetDoc.path}${search}${hash}`;
  }

  collectPreferredVersionsByPluginId(
    allDocsData: {[pluginId: string]: GlobalPluginData},
    state: PreferredVersionState,
  ): {[pluginId: string]: GlobalVersion | null} {
    this.preferredVersionNames = state;
    const result: {[pluginId: string]: GlobalVersion | null} = {};
    Object.keys(allDocsData).forEach((pluginId) => {
      const pluginData = allDocsData[pluginId];
      const pluginState = state[pluginId];
      if (!pluginData || !pluginState) {
        result[pluginId] = null;
        return;
      }
      result[pluginId] = this.resolvePreferredVersion(
        pluginData.versions,
        pluginState.preferredVersionName,
      );
    });
    return result;
  }
}

